{"content": """"Verification harness: run each student's twoSum against the homework2 example test cases."""
import importlib.util

CASES = [
    ([2, 7, 11, 15], 9, [0, 1]),
    ([3, 2, 4], 6, [1, 2]),
    ([3, 3], 6, [0, 1]),
]

FILES = {
    "shirley_rodriguez": "shirley_rodriguez_two_sum.py",
    "donald_richardson": "donald_richardson_two_sum.py",
    "alice_ward": "alice_ward_two_sum.py",
    "timothy_ruiz_v1": "timothy_ruiz_two_sum.py",
    "timothy_ruiz_v2": "timothy_ruiz_two_sum_v2.py",
    "martha_watson": "martha_watson_two_sum.py",
    "frank_phillips": "frank_phillips_two_sum.py",
}

for name, path in FILES.items():
    print(f"--- {name} ---")
    try:
        spec = importlib.util.spec_from_file_location(name, path)
        mod = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(mod)
    except Exception as e:
        print(f"  IMPORT/SYNTAX ERROR: {type(e).__name__}: {e}")
        continue
    fn = getattr(mod, "twoSum", None)
    if fn is None:
        print("  MISSING twoSum function")
        continue
    all_ok = True
    for nums, target, expected in CASES:
        try:
            got = fn(list(nums), target)
        except Exception as e:
            print(f"  nums={nums} target={target}: RUNTIME ERROR {type(e).__name__}: {e}")
            all_ok = False
            continue
        status = "OK" if got == expected else "WRONG"
        if got != expected:
            all_ok = False
        print(f"  nums={nums} target={target}: got={got} expected={expected} -> {status}")
    print(f"  RESULT: {'CORRECT' if all_ok else 'INCORRECT'}")
