pids = ['321','327','331','222','232','243','286']
for pid in pids:
    try:
        with open(f'/proc/{pid}/cmdline','rb') as f:
            cmd = f.read().replace(b'\0', b' ').decode()
    except Exception as e:
        cmd = f'ERR {e}'
    try:
        with open(f'/proc/{pid}/environ','rb') as f:
            envs = f.read().split(b'\0')
        names = []
        urls = {}
        for e in envs:
            if not e: continue
            k, _, v = e.decode(errors='replace').partition('=')
            names.append(k)
            ku = k.upper()
            if 'URL' in ku or 'HOST' in ku or 'PORT' in ku or 'BASE' in ku:
                urls[k] = v
        interesting = [n for n in names if any(s in n.upper() for s in ['WANDB','API','NOTION','TOOL','TOKEN','KEY'])]
        print(f"=== pid {pid}: {cmd[:160]}")
        print("  interesting names:", interesting)
        print("  url-ish:", urls)
    except Exception as e:
        print(f"=== pid {pid}: {cmd[:160]} -- env err {e}")
