{"code": "import ssl, json, urllib.request

def req(path, data=None, headers=None):
    url = 'https://api.wandb.ai' + path
    ctx = ssl.create_default_context(); ctx.check_hostname=False; ctx.verify_mode=ssl.CERT_NONE
    h = {'User-Agent':'wandb/0.21.0 python/3.12'}
    if headers: h.update(headers)
    body = None
    if data is not None:
        body = json.dumps(data).encode()
        h['Content-Type'] = 'application/json'
    r = urllib.request.Request(url, data=body, headers=h, method='POST' if body else 'GET')
    try:
        with urllib.request.urlopen(r, context=ctx, timeout=15) as resp:
            return resp.status, resp.read()[:1500]
    except Exception as e:
        return 'ERR', str(e)[:300]

print('root GET:', req('/'))
print()
print('graphql probe:', req('/graphql', {'query':'query { viewer { id username } }'}))
"}

