 'LiveCodeBench':'val-core/codegen__livecodebench/acc/mean@1',
 'HumanEval':'val-core/codegen__humaneval/acc/mean@1',
}

GROUPS = {
 'guru-nocliphigh-qwen2.5-32b': ['ma1txjj5'],
 '341943-guru92k-cliphigh-qwen32b-Qwen2.5-32B-think': ['qdm5cwl6','9mmkwskw','ihdboejo','it75fa5k'],  # listed in observed order
 '342297-guru92k-nocliphigh-qwen32b-Qwen2.5-32B-think': ['prwodjfw'],
}

def load(rn):
    hist = json.load(open(f'hist_{rn}.json'))
    out = {}
    for row in hist:
        d = json.loads(row)
        st = d.get('_step')
        vals = {b: d[k] for b,k in BENCH.items() if d.get(k) is not None}
        if vals:
            out[st] = vals
    return out

import statistics
results = {}
for gname, rlist in GROUPS.items():
    runs = {rn: load(rn) for rn in rlist}
    # merge per policy: 'later' (later in rlist wins), 'first', 'max'
    policies = ['later','first','max']
    merged = {p: {} for p in policies}
    for p in policies:
        m = {}
        for rn in rlist:
            for st, vals in runs[rn].items():
                if st not in m:
                    m[st] = dict(vals)
                else:
                    for b,v in vals.items():
                        if b not in m[st]: m[st][b]=v
                        else:
                            if p=='later': m[st][b]=v
                            elif p=='first': pass
                            else: m[st][b]=max(m[st][b], v)
        merged[p]=m
    res = {'runs': len(rlist), 'steps': len(merged['later'])}
    # per-benchmark max over merged (policy-independent)
    bench_max = {}
    for b in BENCH:
        vals = [m[b] for m in merged['later'].values() if b in m]
        bench_max[b] = max(vals)
    res['bench_max'] = bench_max
    res['bench_max_mean'] = sum(bench_max.values())/len(bench_max)
    # per-step average, best step per policy
    for p in policies:
        avgs = {st: sum(v.values())/len(v) for st,v in merged[p].items()}
        best_st = max(avgs, key=lambda s: avgs[s])
        res[f'best_{p}'] = (best_st, avgs[best_st], len(merged[p][best_st]))
    results[gname] = res

json.dump(results, open('analysis_results.json','w'), indent=1)
for g, r in results.items():
