    print('   per-bench max:', {b: round(v,6) for b,v in r['bench_max'].items()})
    print('   mean of maxima:', round(r['bench_max_mean'],6))
    for p in ['later','first','max']:
        st, avg, n = r[f'best_{p}']
        print(f'   best step ({p} policy): {st}  avg={round(avg,6)}  nmetrics={n}')
