WHERE cs.points = (SELECT MAX(cs2.points) FROM constructor_standings cs2 WHERE cs2.race_id = r.race_id)
ORDER BY r.year, cs.position
""")
std_ctor = {}
for y, c, p, pos in cur.fetchall():
    std_ctor.setdefault(y, []).append((c, p, pos))

