GROUP BY r.year, res.driver_id""")
raw_drv = defaultdict(list)
for y, d, p in cur.fetchall(): raw_drv[y].append((d, float(p)))
cur.execute("""
SELECT r.year, res.constructor_id, SUM(res.points) FROM results res JOIN races r ON res.race_id=r.race_id
GROUP BY r.year, res.constructor_id""")
raw_ctor = defaultdict(list)
for y, c, p in cur.fetchall(): raw_ctor[y].append((c, float(p)))

def names_drv(ids):
    cur.execute("SELECT driver_id, CONCAT(forename,' ',surname) FROM drivers WHERE driver_id IN (%s)" % ",".join(map(str,ids)))
