    if y >= 1958 and y in std_ctor:
        c, p2, pos2 = sorted(std_ctor[y], key=lambda t: (t[2] if t[2] else 99))[0]
        cname = names_ctor([c])[c]
    else:
        c, p3 = max(raw_ctor[y], key=lambda t: t[1])
        cname = names_ctor([c])[c]
    malike[y] = (dname, cname)

# compare with local309_a
ra = list(csv.reader(io.StringIO(gold["local309_a.csv"])))
A = {int(r[0]): (r[1], r[2]) for r in ra[1:] if r and r[0]}
print("\n-- mismatch M_a_LIKE vs local309_a --")
for y in sorted(A):
    if malike.get(y) != A[y]:
        print(y, "ours:", malike.get(y), "gold_a:", A[y])

# compare with _c
rc = list(csv.reader(io.StringIO(gold["local309_c.csv"])))
C = {int(r[0]): (r[1], r[2]) for r in rc[1:] if r and r[0]}
print("\n-- mismatch M_a_LIKE vs local309_c (ctor col) --")
for y in sorted(C):
    if C[y][0] != malike.get(y, (None,None))[0]: print("drv", y, C[y], malike.get(y))
    gcor = C[y][1]; ocor = malike.get(y,(None,None))[1]
    if gcor != ocor and not (gcor=="" and y<1958): print("ctor", y, repr(gcor), repr(ocor))

# ---------- Q2: parse local354 variants ----------
print("\n===== local354 gold variants =====")
id_sets = []
for c in "abcdefgh":
    rr = [r for r in csv.reader(io.StringIO(gold[f"local354_{c}.csv"])) if r]
    hdr = rr[0]
    rows = rr[1:]
    if hdr[:1] == ["driver_id"] or (len(hdr)==1 and hdr[0]=="driver_id"):
        ids = sorted(int(r[0]) for r in rows if r[0].strip())
        id_sets.append((c, "id", set(ids), ids))
    elif "forename" in hdr and "surname" in hdr:
        fi, si = hdr.index("forename"), hdr.index("surname")
        pairs = [(r[fi], r[si]) for r in rows if len(r)>si]
        cur.execute("SELECT CONCAT(forename,' ',surname), driver_id FROM drivers")
        m = {k:v for k,v in cur.fetchall()}
        missing = [p for p in pairs if f"{p[0]} {p[1]}" not in m]
        ids = sorted(m[f"{p[0]} {p[1]}"] for p in pairs if f"{p[0]} {p[1]}" in m)
        id_sets.append((c, "name", set(ids), ids))
        if missing: print(c, "unmapped names:", missing[:5])
