cur.execute("SELECT year, MIN(round), MAX(round) FROM races WHERE year BETWEEN 1950 AND 1959 GROUP BY year")
sr = {y:(mn,mx) for y,mn,mx in cur.fetchall()}
V1, V2, V3 = set(), set(), set()
for (y,d), rdmap in seasons.items():
