print("=== listening TCP sockets (/proc/net/tcp) ===")
def listen_socks(path, fam):
    try:
        lines = open(path).read().splitlines()[1:]
    except Exception as e:
        print(path, "ERR", e); return []
    out = []
    for l in lines:
        parts = l.split()
        if len(parts) > 9 and parts[3] == "0A":
            ip, port = parts[1].split(":")
            port = int(port, 16)
            ip = ".".join(str(int(ip[i:i+2], 16)) for i in (6, 4, 2, 0)) if fam == 4 else ip
            out.append((ip, port, parts[9]))
    return out
for pth, fam in [("/proc/net/tcp", 4), ("/proc/net/tcp6", 6)]:
    for ip, port, inode in listen_socks(pth, fam):
        print(f"{pth} LISTEN {ip}:{port} inode={inode}")

