BC = {m: round(bz_me[m],4) for m in months_all}
S = {m: round(BC[m]-WC[m],4) for m in months_all}

print("== month-end closes ==")
for m in months_all:
    print(m, WC[m], BC[m], S[m])

T = months_all[-13:-1]  # 12 complete months: 2025-09..2026-08
print("window:", T[0], "..", T[-1], "n =", len(T))

def moms(series_months):
    out = {}
    for i, m in enumerate(series_months):
        if i == 0:
            out[m] = None
            continue
        out[m] = round((series_months[i]/series_months[i-1]-1)*100, 2)
    return out

def zseries(ms, spreads, window=None):
    """z per month in ms using trailing up-to-6 spreads; window adjusts start offset."""
    out = {}
    vals = [spreads[m] for m in ms]
    for i, m in enumerate(ms):
        lo = max(0, i-5)
        w = vals[lo:i+1]
        if len(w) < 4:
            out[m] = 0.0
            continue
        mu = sum(w)/len(w)
        var = sum((x-mu)**2 for x in w)/(len(w)-1)
        sd = math.sqrt(var)
        z = 0.0 if sd == 0 else (vals[i]-mu)/sd
        out[m] = max(-3.0, min(3.0, z))
    return out

# Configs: A = 12-month series only; C = 13-month series (2025-08..); B = full hist 2025-04..
cfgA = zseries(T, S)
cfgC = zseries(months_all[-14:-1], S)  # 2025-08..2026-08
cfgB = {}
vals_full = [S[m] for m in months_all]
idx = {m: i for i, m in enumerate(months_all)}
for m in T:
    i = idx[m]
    w = vals_full[max(0, i-5):i+1]
    mu = sum(w)/len(w); var = sum((x-mu)**2 for x in w)/(len(w)-1); sd = math.sqrt(var)
    z = 0.0 if sd == 0 else (vals_full[i]-mu)/sd
    cfgB[m] = max(-3.0, min(3.0, z))

def sig(z):
    if z <= -1: return "Long Spread"
    if z >= 1: return "Short Spread"
    return "Flat"

print()
print("== z-scores & signals ==")
print("month     | zA     zA_sig        | zC     zC_sig        | zB     zB_sig")
for m in T:
    print(f"{m} | {cfgA[m]:+.4f} {sig(cfgA[m]):12s} | {cfgC[m]:+.4f} {sig(cfgC[m]):12s} | {cfgB[m]:+.4f} {sig(cfgB[m]):12s}")

def trades_from(sigs, which_z):
