    main_by_file.setdefault(p, []).append((l, v['text']))
for (p, l), v in dev.items():
    dev_by_file.setdefault(p, []).append((l, v['text']))
for d in (main_by_file, dev_by_file):
    for p in d:
        d[p].sort()

changed_files = set(main_by_file) | set(dev_by_file)
delta_report = {}
for p in sorted(changed_files):
    a = main_by_file.get(p, [])
    b = dev_by_file.get(p, [])
    if [t for _, t in a] == [t for _, t in b] and [l for l, _ in a] == [l for l, _ in b]:
        continue
    sm = difflib.SequenceMatcher(a=[t for _, t in a], b=[t for _, t in b], autojunk=False)
    removed, added, moved = [], [], []
    for tag, i1, i2, j1, j2 in sm.get_opcodes():
        if tag == 'equal':
            for k in range(i2 - i1):
                if a[i1 + k][0] != b[j1 + k][0]:
                    moved.append((a[i1 + k][0], b[j1 + k][0], a[i1 + k][1]))
        elif tag == 'delete':
            removed += [(l, t) for l, t in a[i1:i2]]
        elif tag == 'insert':
            added += [(l, t) for l, t in b[j1:j2]]
        else:  # replace
            removed += [(l, t) for l, t in a[i1:i2]]
            added += [(l, t) for l, t in b[j1:j2]]
    delta_report[p] = {'removed': removed, 'added': added, 'moved': moved}

