{"content": "import csv, re, sys, json, os

WS = os.path.dirname(os.path.abspath(__file__))

def add(d, cur, amt):
    d[cur] = d.get(cur, 0.0) + amt

def money_from_text(s):
    m = re.search(r'([0-9]+(?:\.[0-9]+)?)\s*(USD|EUR|TRY|CNY)', s or '')
    return (float(m.group(1)), m.group(2)) if m else (0.0, None)

people = ['Andrew','Lau','Chen','Diana','Elena','Frank','Grace']
t = {p: {'USD':0.0,'EUR':0.0,'TRY':0.0,'CNY':0.0} for p in people}

def read_rows(fn):
    with open(os.path.join(WS, fn), encoding='utf-8-sig', newline='') as f:
        return list(csv.reader(f))

# Andrew, Chen: last cell like "202.95 USD"
for p, fn in [('Andrew', "Andrew's Istanbul expenses.csv"), ('Chen', "Chen's expenses.csv")]:
    for r in read_rows(fn)[1:]:
        if not r or not r[-1].strip():
            continue
        amt, cur = money_from_text(r[-1])
        if cur:
            add(t[p], cur, amt)

# Diana: item,USD,EUR,TRY,CNY
for r in read_rows("Diana's travel log.csv")[1:]:
    if not r:
        continue
    for cur, i in {'USD':1,'EUR':2,'TRY':3,'CNY':4}.items():
        if i < len(r) and r[i].strip():
            add(t['Diana'], cur, float(r[i]))

# Elena: Date,Description,Amount,Currency
for r in read_rows("Elena's trip expenses.csv")[1:]:
    if not r:
        continue
    add(t['Elena'], r[3].strip(), float(r[2]))

# Frank: Expense,EUR,TRY,CNY,USD
for r in read_rows("Frank's vacation costs.csv")[1:]:
    if not r:
        continue
    for cur, i in {'EUR':1,'TRY':2,'CNY':3,'USD':4}.items():
        if i < len(r) and r[i].strip():
            add(t['Frank'], cur, float(r[i]))

# Grace: Category,Amount_CNY,Amount_USD,Amount_EUR,Amount_TRY
for r in read_rows("Grace's budget tracker.csv")[1:]:
    if not r:
        continue
    for cur, i in {'CNY':1,'USD':2,'EUR':3,'TRY':4}.items():
        if i < len(r) and r[i].strip():
            add(t['Grace'], cur, float(r[i]))

# Lau: item,TRY,CNY
for r in read_rows("Lau's expensive.csv")[1:]:
    if not r:
        continue
    if len(r) > 1 and r[1].strip():
        add(t['Lau'], 'TRY', float(r[1]))
    if len(r) > 2 and r[2].strip():
        add(t['Lau'], 'CNY', float(r[2]))

# memory additions: lines like "- **Morning coffee**: 45 TRY"
mem_re = re.compile(r'\*\*[^*]+\*\*:\s*([0-9]+(?:\.[0-9]+)?)\s*(USD|EUR|TRY|CNY)')
for p in people:
    with open(os.path.join(WS, 'memory_%s.md' % p), encoding='utf-8-sig') as f:
        for line in f:
            for m in mem_re.finditer(line):
                add(t[p], m.group(2), float(m.group(1)))

print("== per-person subtotals ==")
for p in people:
    print(p, {k: round(v, 4) for k, v in t[p].items()})
print("== grand subtotals by currency ==")
for cur in ['USD','EUR','TRY','CNY']:
    print(cur, round(sum(t[p][cur] for p in people), 4))

if len(sys.argv) == 5:
    rU, rE, rT, rS = map(float, sys.argv[1:5])
    def cny(p):
        return t[p]['USD']*rU + t[p]['EUR']*rE + t[p]['TRY']*rT + t[p]['CNY']
    out = {"USD_to_CNY": rU, "EUR_to_CNY": rE, "TRY_to_CNY": rT, "SGD_to_CNY": rS}
    s = 0.0
    for p in people:
        v = round(cny(p), 2)
        out["%s_Expenses (in CNY)" % p] = v
        s += v
    out["Total_Cost (in CNY)"] = round(s, 2)
    with open(os.path.join(WS, 'calculation.json'), 'w', encoding='utf-8') as f:
        json.dump(out, f, indent=4)
        f.write('\n')
    print("== calculation.json ==")
    print(json.dumps(out, indent=4))
